const data = $input.first().json;
const panels = data.panels || [];
const summary = panels.map(p => {
  const name = p.name;
  const metrics = p.data ? Object.entries(p.data)
    .filter(([_, v]) => typeof v === 'number' || typeof v === 'string')
    .slice(0, 3)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ') : 'no data';
  return `${name}: ${metrics}`;
}).join('\n');
return [{ json: { summary, configured: data.configured, total: data.total, health: data.globalHealth } }];

